package main

import (
    "log"
    "os"
    "os/signal"
    "syscall"
    "time"
)

func main() {
    // Set up regular log file for application logs
    logFile, err := os.OpenFile("app.log", os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0666)
    if err != nil {
        log.Fatalf("error opening log file: %v", err)
    }
    defer logFile.Close()

    log.SetOutput(logFile)
    log.Println("应用程序启动")

    // Create a channel to receive system signals
    sigs := make(chan os.Signal, 1)
    // Listen for SIGTERM and SIGINT signals
    signal.Notify(sigs, syscall.SIGTERM, syscall.SIGINT)

    go func() {
        // Wait for termination signal
        sig := <-sigs
        log.Printf("收到信号: %s, 正在关闭应用程序...", sig)

        // Simulate cleanup work
        time.Sleep(2 * time.Second)
        log.Println("清理工作完成，应用程序已关闭")

        // Write termination message to /tmp/my-termination-message
        terminationFile, err := os.OpenFile("/tmp/my-termination-message", os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0666)
        if err != nil {
            log.Fatalf("error opening termination message file: %v", err)
        }
        defer terminationFile.Close()

        terminationFile.WriteString("Application terminated gracefully.\n")
        os.Exit(0)
    }()

    // Simulate the main loop of the application
    for {
        log.Println("应用程序正在运行...")
        time.Sleep(1000 * time.Second)
    }
}

